import { test } from 'node:test';
import * as assert from 'node:assert/strict';
import * as fs from 'node:fs';
import * as path from 'node:path';
import * as os from 'node:os';

/**
 * Acceptance test for linux-socket-territory-observation-capcell-fabrication.
 * Target: ../linux-socket-territory-observation-capcell-fabrication.mjs
 */

const tmpDir = fs.mkdtempSync(path.join(os.tmpdir(), 'capcell-test-'));

test('exact-loopback-tcp-territory', async () => {
  const { observeLinuxSocketTerritory } = await import('../linux-socket-territory-observation-capcell-fabrication.mjs');

  // Verify API existence
  assert.equal(typeof observeLinuxSocketTerritory, 'function', 'API export missing');

  // Inject a mock snapshot simulating /proc/net/tcp for localhost
  const mockSnapshot = [
    'sl  local_address rem_address   st tx_queue rx_queue tr tm->when retrnsmt   uid  timeout inode',
    '1: 0100007F:0050 00000000:0000 0A 00000000:00000000 00:00000000 00000000  1000        0 12345'
  ].join('\n');

  const policy = { admissibleDenominator: '10' };

  const result = observeLinuxSocketTerritory({
    snapshot: mockSnapshot,
    policy,
    context: { ns: 'host', family: 'inet', proto: 'tcp' }
  });

  // Verify constraints
  assert.ok(result.capacity, 'Missing capacity');
  assert.ok(result.occupancy, 'Missing occupancy');
  assert.equal(typeof result.capacity.numerator, 'string');
  assert.equal(typeof result.capacity.denominator, 'string');

  // Assert reduced exact fractions (1 occupied, 10 admissible -> 1/10)
  assert.equal(result.occupancy.numerator, '1');
  assert.equal(result.occupancy.denominator, '10');

  // Assert berth distribution
  assert.ok(result.berths.every(b => b.share === '1/10'), 'Invalid berth share');

  // Forbidden check: no floating points
  const raw = JSON.stringify(result);
  assert.ok(!raw.includes('.'), 'Floating point detected');
});

test('typed-observation-refusal', async () => {
  const { observeLinuxSocketTerritory } = await import('../linux-socket-territory-observation-capcell-fabrication.mjs');

  // Simulate unobservable state (missing kernel interface)
  const result = observeLinuxSocketTerritory({
    snapshot: null,
    policy: { admissibleDenominator: '1' },
    context: { ns: 'unreachable', family: 'inet6', proto: 'udp' }
  });

  // Assert typed refusal
  assert.equal(result.status, 'refused');
  assert.ok(result.reason.includes('unobservable'), 'Refusal must identify missing observation');

  // Forbidden check: no zeros for unknown measurements
  assert.notEqual(result.occupancy, 0, 'Zero measurement fabricated for unknown state');
});

// Cleanup
test.after(() => {
  fs.rmSync(tmpDir, { recursive: true, force: true });
});
